22	public class CheckOwnerHouseholdUnique {
23	
24	    public void service(@Val Owner owner, @Val Boolean sharesHousehold,
25	            OwnerRepository ownerRepository) throws DuplicateHouseholdException {
26	        String lastName = key(owner.getLastName());
27	        String address = AddressNormalizer.normalize(owner.getAddress());
28	        List<Owner> household = new ArrayList<>();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
31	                continue; // same record (e.g. re-save), not a conflict
32	            }
33	            if (lastName.equals(key(existing.getLastName()))
34	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
35	                household.add(existing);
36	            }
37	        }
38	        if (household.isEmpty()) {
39	            owner.setHouseholdSize(1); // a household of one: just this new owner
40	            return; // no existing owner at this last name + address
41	        }
42	        if (!Boolean.TRUE.equals(sharesHousehold)) {
43	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
44	        }
45	        // Explicitly allowed to share: assign the same stable household identifier to all members,
46	        // and record the household's size (existing members plus this new owner) on every member so
47	        // it reflects the household as it stands after this create.
48	        String householdId = householdId(lastName, address, household);
49	        int householdSize = household.size() + 1;
50	        owner.setHouseholdId(householdId);
51	        owner.setHouseholdSize(householdSize);
52	        for (Owner member : household) {
53	            member.setHouseholdId(householdId);
54	            member.setHouseholdSize(householdSize);
