74	    private static String sha256Hex(String value) {
75	        try {
76	            byte[] digest = MessageDigest.getInstance("SHA-256")
77	                    .digest(value.getBytes(StandardCharsets.UTF_8));
78	            StringBuilder sb = new StringBuilder(digest.length * 2);
79	            for (byte b : digest) {
